-- Surat keterangan is no longer uploaded by Tim MB but generated by the backend from a template
-- and signed with Ed25519, so that a copy can be checked against the original.
--
-- isi:          the printed data, frozen at issue as JSON. The signature covers exactly these
--               bytes, so later changes to the mahasiswa or the position do not alter the surat.
-- tanda_tangan: base64url Ed25519 signature over isi, also carried in the QR code.
-- hash_berkas:  SHA-256 of the issued PDF, to recognise an uploaded copy byte for byte.
--
-- No endpoint ever wrote this table, so it is expected to be empty. Should it hold rows, this
-- migration fails instead of inventing signatures for them.
ALTER TABLE surat_keterangan
    ADD COLUMN nomor_surat VARCHAR(100) NOT NULL UNIQUE,
    ADD COLUMN isi TEXT NOT NULL,
    ADD COLUMN tanda_tangan VARCHAR(100) NOT NULL,
    ADD COLUMN hash_berkas CHAR(64) NOT NULL UNIQUE;
